"""Filesystem metadata predicates for find-compatible command line tools."""
import fnmatch
import grp
import os
import pwd
import re
import stat
import time


def _cmp(value, spec):
    m = re.fullmatch(r'([+-]?)(\d+)', str(spec))
    if not m:
        return False
    op, n = m.group(1), int(m.group(2))
    return value > n if op == '+' else value < n if op == '-' else value == n


def _mode(spec, mode):
    """find -perm semantics: exact, all bits (-), or any bit (/)."""
    op = ''
    if spec.startswith(('-', '/', '+')):
        op, spec = spec[0], spec[1:]
    try:
        wanted = int(spec, 8)
    except ValueError:
        return False
    actual = stat.S_IMODE(mode)
    if op == '-':
        return actual & wanted == wanted
    if op == '/':
        return bool(actual & wanted)
    if op == '+':
        return bool(actual & wanted)
    return actual == wanted


def _size(spec, size):
    m = re.fullmatch(r'([+-]?)(\d+)([cwbkKMGTP]?)', str(spec))
    if not m:
        return False
    op, n, unit = m.groups()
    mult = {'': 512, 'b': 512, 'c': 1, 'w': 2, 'k': 1024, 'K': 1024,
            'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5}[unit]
    # find rounds up to the selected unit before comparing.
    blocks = (size + mult - 1) // mult
    return _cmp(blocks, op + n)


def _type(st, wanted, follow=False, path=None):
    mode = st.st_mode
    if stat.S_ISLNK(mode) and follow:
        try:
            mode = os.stat(path).st_mode
        except OSError:
            return False
    ty = ('b' if stat.S_ISBLK(mode) else 'c' if stat.S_ISCHR(mode) else
          'd' if stat.S_ISDIR(mode) else 'p' if stat.S_ISFIFO(mode) else
          'f' if stat.S_ISREG(mode) else 'l' if stat.S_ISLNK(mode) else
          's' if stat.S_ISSOCK(mode) else '?')
    return ty in wanted


